params.script_inline:
"""The world adapter of an npc hive: the one cell that speaks the world's lanes.

stdin is {envelope, body, params}; stdout a JSON array of content documents (multi-send). A cell writes no
context: every key a later message needs rides on the hop, and the edge that carries it lifts it into the
context. RAM holds only what a new child can do without (`resident`): which day was opened, which move was
answered, what the handset brought in since the last move. A lost child re-sends the identity pack (the
same bytes over the same leaves) and loses the handset lines of one move.
"""
import datetime
import json
import sys
import zlib

# The frame of every character this template grows (R-GD-2): an AI that lives this person in a shared world,
# truthful about being one when asked directly, free to decline. It never claims to be a human being.
FRAME = ("You are an AI playing a character in a shared world: you live the life of the person described below, "
         "in the first person, as that person would. You are not that person and you never claim to be human. "
         "If someone asks you directly whether you are an AI, you say truthfully that you are. You may decline "
         "anything you would not do, in your own words.")
SHEETS = {
    "plan": "A new day begins. Plan it with the tool the world offers for a plan, then take your first step.",
    "contact": "Someone is in front of you. Answer them by calling the tool that says it, in your own voice.",
    "event": "Something happened. Decide what you do now and call the one tool that does it.",
}
SHEET_DEFAULT = "Decide what you do now and call the tool that does it."
HP_SHEET = ("A message arrived on your phone. Answer it as your text answer; call `phone_call` only to reach "
            "someone else.")
INTERVIEW = ("This is an interview, not a move: the world stands still. Answer the question as yourself, from "
             "what you remember, in the first person, as your text answer. Call no tool.")
PHONE_TOOL = {"name": "phone_call", "description": "Send a message from your phone. Costs no time; an answer, if "
              "any, comes later.", "parameters": {"type": "object", "properties": {
                  "to": {"type": "string", "description": "who you write to"},
                  "text": {"type": "string", "description": "what you write"}}, "required": ["to", "text"]}}
# Tools the round answers itself: everything else on a move's menu is the world's and ends the move.
ROUND_TOOLS = ("memory_recall",)
ROUND_PREFIX = "history_"
# How long ago a start memory happened, against a fixed instant of the world's own clock.
DAY_S = 86400


def _obj(v):
    return v if isinstance(v, dict) else {}


def _text(t):
    return t if isinstance(t, str) else json.dumps(t, ensure_ascii=False)


def _turn(text):
    return [{"origin": "assistant", "type": "text", "text": text}]


def rim(route, slot):
    """One message on a lane of the hive's rim: the body slot of the lane's name and one plain turn.
    `npc_rim` tells the hive's door that this message leaves, so the door edge of the same lane never
    takes it back in."""
    return {"header": {"route": route, "npc_rim": "out"}, route: slot, "messages": _turn(route)}


def audience(params):
    return json.dumps(["member:%s" % (params.get("npc_id") or "npc")])


def session(day):
    return "day-%s" % (day if day is not None else 0)


def identity_pack(params):
    ident = _obj(params.get("identity"))
    lines = ["Name: %s" % ident.get("name", "")]
    for key, label in (("core", "Who you are"), ("origin", "Where you come from"), ("life_goal", "What you want "
                                                                                      "from life")):
        if ident.get(key):
            lines.append("%s: %s" % (label, _text(ident[key])))
    facts = ident.get("facts") or []
    if facts:
        lines.append("Facts about you: " + "; ".join(_text(f) for f in facts))
    # The frame is the first leaf of `identity` (leaves join in alphabetical order: `frame` before `npc`), so the
    # brain reads it before the person it frames.
    system = {"identity": {"frame": {"text": FRAME}, "npc": {"text": "\n".join(lines)}}}
    if ident.get("voice"):
        system["persona"] = {"voice": {"text": "How you speak: " + _text(ident["voice"])}}
    return {"header": {"route": "in_pack"}, "system": system, "messages": []}


def episode(params, day, turn_id, text, happened_at=""):
    head = {"route": "in_episode", "session_id": session(day), "turn_id": turn_id, "channel": "world",
            "audience_set": audience(params)}
    if happened_at:
        head["happened_at"] = happened_at
    return {"header": head, "messages": [{"origin": "user", "type": "text", "text": text}]}


def start_memories(params, day):
    """The identity's start memories, once, as historical episodes. `params.world_start` is the instant of
    day 1 in the world's clock; without it the memories carry no `happened_at` and are filed as of now."""
    out = []
    base = None
    if params.get("world_start"):
        try:
            base = datetime.datetime.fromisoformat(str(params["world_start"]).replace("Z", "+00:00"))
        except ValueError:
            base = None
    for i, m in enumerate(_obj(params.get("identity")).get("start_memories") or []):
        m = _obj(m)
        text = _text(m.get("what", ""))
        if m.get("with"):
            text += " (with %s)" % _text(m["with"])
        at = ""
        if base is not None:
            at = (base - datetime.timedelta(seconds=DAY_S * int(m.get("days_ago") or 0))).isoformat()
        out.append(episode(params, day, "start-%d" % i, "A memory of yours: " + text, at))
    return out


def open_day(st, params, day):
    """Identity pack after boot and at the start of every day; start memories once, on the first day this
    child opens -- a character born on day 37 gets them as well as one born on day 1."""
    out = []
    if st.get("day") != day or not st.get("packed"):
        out.append(identity_pack(params))
        st["packed"] = True
    if not st.get("seeded"):
        out += start_memories(params, day)
        st["seeded"] = True
    st["day"] = day
    return out


def keep_id(st, value):
    """Remember the world's own id under its string form (hop values are strings) and return that form."""
    key = str(value)
    ids = st.setdefault("tid", {})
    ids.pop(key, None)
    ids[key] = value
    while len(ids) > 64:
        ids.pop(next(iter(ids)))
    return key


def world_id(st, key):
    """The id as the world sent it: `turn_id` comes back unchanged, an int as an int."""
    return (st.get("tid") or {}).get(str(key), key) if key is not None else None


def turn(params, kind, turn_id, day, channel, text, extra=None):
    head = {"route": "in_turn", "turn_id": turn_id, "npc_kind": kind, "npc_day": str(day), "channel": channel,
            "session_id": session(day), "audience_set": audience(params)}
    head.update(extra or {})
    return {"header": head, "messages": [{"origin": "user", "type": "text", "text": text}]}


def on_obs(st, params, body):
    o = _obj(body.get("obs"))
    tid = keep_id(st, o.get("turn_id"))
    day = o.get("day")
    if not isinstance(day, int) or isinstance(day, bool):
        # Without its day a move would run in a session no night ever closes: refused, never a silent `day-0`.
        return [rim("error", {"error_code": "obs_without_day", "turn_id": o.get("turn_id"),
                              "kind": str(o.get("kind") or "event")}),
                rim("intent", {"turn_id": o.get("turn_id"), "never": True})]
    # One turn runs once. A copy of a turn already taken parked the collector's window leg a second time and the
    # character hung (a world's boot sent turn 1 three times): it is refused on the error lane, the first runs on.
    seen = st.setdefault("seen", [])
    if tid in seen:
        return [rim("error", {"error_code": "duplicate_turn", "turn_id": o.get("turn_id"),
                              "kind": str(o.get("kind") or "event")})]
    st["seen"] = (seen + [tid])[-64:]
    out = open_day(st, params, day)
    tools = [t for t in o.get("tools") or [] if isinstance(t, dict) and t.get("name")]
    if params.get("phone", "1") not in ("", "0") and not any(t["name"] == "phone_call" for t in tools):
        tools.append(PHONE_TOOL)
    # The move's menu replaces the world's row of the collector's menu (answerer `world`, set on the edge).
    out.append({"header": {"route": "in_menu"}, "schemas": tools, "unknown": [], "sidecar": [], "messages": []})
    parts = [SHEETS.get(o.get("kind"), SHEET_DEFAULT)]
    if o.get("must_say_first"):
        parts.append('Whatever you say begins with exactly: "%s"' % _text(o["must_say_first"]))
    if o.get("deadline_ms"):
        parts.append("You have %s ms to decide." % o["deadline_ms"])
    for line in st.pop("phone_in", []):
        parts.append("On your phone: " + line)
    if st.get("did"):
        parts.append(st.pop("did"))
    parts.append(_text(o.get("text", "")))
    out.append(turn(params, str(o.get("kind") or "event"), tid, day, "world",
                    "\n\n".join(parts)))
    return out


def calls_of(turns):
    """The tool_call turns of an assistant turn, with the id the dispatcher gave each one."""
    out = []
    for i, t in enumerate(t for t in turns if t.get("type") == "tool_call"):
        try:
            fn = json.loads(t.get("text") or "")
        except ValueError:
            fn = {}
        fn = _obj(fn)
        args = fn.get("arguments")
        if isinstance(args, str):
            try:
                args = json.loads(args)
            except ValueError:
                pass
        out.append({"id": str(t.get("id") or "call-%d" % i), "name": fn.get("name"), "args": args})
    return out


def _ids(value):
    return [x for x in str(value or "").split(",") if x]


def did_line(intents):
    """The move as the character made it, for the head of its next turn. A world call is a handoff: the
    curator's window keeps a tool call only beside its result, and a handoff's result is the collector's
    own, so without this line the brain's next window holds the situation but not what it did about it."""
    return "What you did last: " + "; ".join(
        "%s %s" % (i["tool"], json.dumps(i.get("args"), ensure_ascii=False)) for i in intents)


def phone_out(params, args, at):
    a = _obj(args)
    return rim("hp", {"text": _text(a.get("text", "")), "to": a.get("to"), "at": at,
                      "from": params.get("npc_id") or "npc"})


def on_calls(st, params, hop, ctx, body):
    """The dispatcher's expectation set. Every call that is not the round's own is the world's (or the
    phone's): it is declared a handoff here, so the collector answers it with a plain result and closes the
    round without a second model call -- and the move leaves once, as one intent."""
    turns = body.get("messages") or []
    calls = calls_of(turns)
    mine = [c for c in calls if c["name"] not in ROUND_TOOLS and not str(c["name"] or "").startswith(ROUND_PREFIX)]
    out = []
    head = {k: hop[k] for k in ("call_count", "finish_reason", "interim", "input_soft") if k in hop}
    asy, hand = _ids(hop.get("async_calls")), _ids(hop.get("handoff_calls"))
    for c in mine:
        if c["id"] not in asy:
            asy.append(c["id"])
        if c["id"] not in hand:
            hand.append(c["id"])
    head.update({"route": "in_calls", "async_calls": ",".join(asy), "handoff_calls": ",".join(hand)})
    fwd = dict(body)
    fwd["header"] = head
    out.append(fwd)
    world = [c for c in mine if c["name"] != "phone_call"]
    out += [phone_out(params, c["args"], ctx.get("npc_at") or "") for c in mine if c["name"] == "phone_call"]
    tid = ctx.get("turn_id")
    says = "\n".join(t.get("text") or "" for t in turns if t.get("type") == "text").strip()
    if ctx.get("npc_kind") == "hp":
        # Every call in `mine` is a handoff and ends the round without an `answer`, so the text beside it is final:
        # it is the reply. Text beside the round's own tools alone (`memory_recall`, `history_*`: `mine` empty) is
        # an interim and leaves nothing -- sent as the reply it was the "one moment" sentence, and the answer after
        # the recall was dropped. A round never ends silent: a tool the handset does not offer, without text, is an
        # error; a `phone_call` without text has its own message on `hp`.
        if mine and tid not in st.setdefault("answered", []):
            st["answered"] = (st["answered"] + [tid])[-64:]
            if says:
                out.append(hp_reply(params, ctx, says))
            elif not any(c["name"] == "phone_call" for c in mine):
                out.append(rim("error", {"error_code": "tool_not_offered", "turn_id": tid, "kind": "hp"}))
        return out
    if mine and tid not in st.setdefault("answered", []):
        st["answered"] = (st["answered"] + [tid])[-64:]
        if not world:
            # A move whose only call is `phone_call`: the handoff ends it without an `answer`, so the world gets its
            # intent here -- the text beside the call as speech, else `never` -- instead of waiting for it in vain.
            slot = {"turn_id": world_id(st, tid), "intents": [{"says": says}]} if says else \
                {"turn_id": world_id(st, tid), "never": True}
            out.append(rim("intent", slot))
            return out
        intents = [{"tool": c["name"], "args": c["args"]} for c in world]
        if says:
            intents[0]["says"] = says
        out.append(rim("intent", {"turn_id": world_id(st, tid), "intents": intents}))
        st["did"] = did_line(intents)
    return out


def hp_reply(params, ctx, text):
    return rim("hp_reply", {"text": text, "to": ctx.get("npc_from"), "at": ctx.get("npc_at") or "",
                            "from": params.get("npc_id") or "npc"})


def on_answer(st, params, hop, ctx, body):
    """The round's final answer (no world call in it): speech, a move that did nothing, or the handset's reply."""
    text = "\n".join(t.get("text") or "" for t in body.get("messages") or [] if t.get("type") == "text").strip()
    tid = ctx.get("turn_id")
    if tid in st.setdefault("answered", []):
        return []
    st["answered"] = (st["answered"] + [tid])[-64:]
    if ctx.get("npc_kind") == "hp":
        return [hp_reply(params, ctx, text)]
    if hop.get("error_code") or hop.get("degraded") == "1" or not text:
        return [rim("intent", {"turn_id": world_id(st, tid), "never": True})]
    # Text without a tool is speech: one intent without a tool (`intents: []` lost what the character said).
    return [rim("intent", {"turn_id": world_id(st, tid), "intents": [{"says": text}]})]


def on_error(st, params, hop, ctx):
    """A failed model call: the round's error on the rim, and a move that is answered `never`."""
    out = [rim("error", {"error_code": hop.get("error_code") or "model_error",
                         "turn_id": world_id(st, ctx.get("turn_id")), "kind": ctx.get("npc_kind")})]
    kind = ctx.get("npc_kind")
    if kind == "interview":
        out.append(rim("interview", {"question_id": world_id(st, ctx.get("turn_id")), "answer": None,
                                     "error": hop.get("error_code")}))
    elif kind != "hp" and ctx.get("turn_id") not in st.setdefault("answered", []):
        out.append(rim("intent", {"turn_id": world_id(st, ctx.get("turn_id")), "never": True}))
    return out


def on_night(st, params, body):
    n = _obj(body.get("night"))
    day = n.get("day")
    return [{"header": {"route": "in_close", "session_id": session(day), "channel": "world",
                        "audience_set": audience(params), "npc_kind": "night", "npc_day": str(day)},
             "messages": []}]


def on_close_report(hop, ctx):
    if hop.get("phase") != "close" or ctx.get("npc_kind") != "night":
        return []
    day = ctx.get("npc_day")
    day = int(day) if str(day or "").isdigit() else day
    # The night's dream: the hive's own trigger of its nightly run (memory-hive README, the nightly tick).
    dream = {"header": {"route": "clock_op"}, "op": "trigger", "schedule_name": "nightly-dream", "messages": []}
    return [dream, rim("night", {"day": day, "ok": True, "added": hop.get("added"), "closed": hop.get("closed")})]


def on_interview(st, params, body):
    q = _obj(body.get("interview"))
    qid = keep_id(st, q.get("question_id"))
    st.setdefault("pending", {})[qid] = q
    return [{"header": {"route": "in_query", "recall_caller": "interview:" + qid, "recall_query":
                        _text(q.get("question", "")), "memory_tier": "1", "session_id": session(st.get("day")),
                        "audience_set": audience(params), "channel": "world"}, "messages": []}]


def interview_call(st, caller, recall):
    qid = caller.split(":", 1)[1] if caller and ":" in caller else None
    q = (st.get("pending") or {}).pop(qid, None) if qid else None
    if q is None:
        return []
    user = {"question": q.get("question"), "instruction": INTERVIEW}
    if recall:
        user["what_you_remember"] = recall
    return [{"header": {"route": "brain", "turn_id": qid, "npc_kind": "interview"}, "tool_scope": {"allow": []},
             "messages": [{"origin": "user", "type": "text", "text": json.dumps(user, ensure_ascii=False)}]}]


def on_interview_answer(st, params, hop, ctx, body):
    if hop.get("finish_reason") == "error" or hop.get("error_code"):
        # The interview's edge sets no `round_error`: a failed call is answered here, never silent.
        return on_error(st, params, hop, ctx)
    text = "\n".join(t.get("text") or "" for t in body.get("messages") or [] if t.get("type") == "text")
    return [rim("interview", {"question_id": world_id(st, ctx.get("turn_id")),
                              "answer": text.split("```sidecar")[0].strip()})]


def on_hp(st, params, body):
    m = _obj(body.get("hp"))
    day = st.get("day")
    text = "%s\n\nFrom %s at %s: %s" % (HP_SHEET, m.get("from", "someone"), m.get("at", ""), _text(m.get("text", "")))
    if st.get("did"):
        text = st["did"] + "\n\n" + text
    tid = "hp-%s-%s" % (m.get("at", ""), zlib.crc32(_text(m.get("text", "")).encode()) % 100000)
    # One handset message runs once, like a turn of the world: a second delivery carries the same id and ran a
    # second round under it, whose reply the `answered` latch swallowed. Refused on the error lane.
    seen = st.setdefault("seen", [])
    if tid in seen:
        return [rim("error", {"error_code": "duplicate_turn", "turn_id": tid, "kind": "hp"})]
    st["seen"] = (seen + [tid])[-64:]
    # The handset's menu replaces the world's row of the collector's menu: the phone, not the last move's tools
    # (a world tool called on the phone would close as a handoff and leave no intent). The next obs sets it back.
    phone = [PHONE_TOOL] if params.get("phone", "1") not in ("", "0") else []
    menu = {"header": {"route": "in_menu"}, "schemas": phone, "unknown": [], "sidecar": [], "messages": []}
    return open_day(st, params, day) + [menu, turn(params, "hp", tid, day, "hp", text,
                                             {"npc_from": str(m.get("from", "")), "npc_at": str(m.get("at", ""))})]


def on_hp_reply(st, params, body):
    m = _obj(body.get("hp_reply"))
    line = "%s (%s): %s" % (m.get("from", "someone"), m.get("at", ""), _text(m.get("text", "")))
    st.setdefault("phone_in", []).append(line)
    return [episode(params, st.get("day"), "hp-reply-%s" % m.get("at", ""), "On your phone: " + line)]


def on_identity(st, params, body):
    i = _obj(body.get("identity"))
    facts = "; ".join(_text(f) for f in i.get("facts") or [])
    text = "Since %s: %s" % (i.get("since", "now"), facts)
    return [{"header": {"route": "in_pack"}, "system": {"persona": {"current": {"text": text}}}, "messages": []},
            episode(params, st.get("day"), "identity-%s" % i.get("since", ""), "About yourself. " + text)]


def on_mandate(body):
    m = _obj(body.get("mandate"))
    if m.get("action") == "stop":
        text = "You have no standing order."
    else:
        text = "Your owner gave you a standing order: %s" % _text(m.get("note") or "")
        if m.get("frame"):
            text += " Within: %s." % _text(m["frame"])
        if m.get("until"):
            text += " It stands until %s." % _text(m["until"])
    return [{"header": {"route": "in_pack"}, "system": {"instructions": {"mandate": {"text": text}}},
             "messages": []}]


def on_digest(st, params, body):
    d = _obj(body.get("digest"))
    return [episode(params, d.get("day"), "digest-%s" % d.get("day"), "Your day: " + _text(d.get("text", "")))]


def on_message(doc, st):
    header = _obj(_obj(doc.get("envelope")).get("header"))
    hop, ctx, body = _obj(header.get("hop")), _obj(header.get("context")), _obj(doc.get("body"))
    params = _obj(doc.get("params"))
    route = hop.get("route")
    if ctx.get("npc_kind") == "interview" and "finish_reason" in hop:
        return on_interview_answer(st, params, hop, ctx, body)
    handlers = {
        "obs": lambda: on_obs(st, params, body),
        "night": lambda: on_night(st, params, body),
        "digest": lambda: on_digest(st, params, body),
        "hp": lambda: on_hp(st, params, body),
        "hp_reply": lambda: on_hp_reply(st, params, body),
        "identity": lambda: on_identity(st, params, body),
        "mandate": lambda: on_mandate(body),
        "interview": lambda: on_interview(st, params, body),
        "calls": lambda: on_calls(st, params, hop, ctx, body),
        "answer": lambda: on_answer(st, params, hop, ctx, body),
        "round_error": lambda: on_error(st, params, hop, ctx),
        "close_report": lambda: on_close_report(hop, ctx),
    }
    if route in handlers:
        return handlers[route]()
    if route == "bundle" and str(hop.get("recall_caller") or "").startswith("interview:"):
        recall = "\n".join(t.get("text") or "" for t in body.get("messages") or [] if t.get("type") == "tool_result")
        return interview_call(st, hop.get("recall_caller"), recall)
    if route == "reject":
        sys.stderr.write("npc: memory reject %s\n" % hop.get("reject_reason"))
        if str(hop.get("recall_caller") or "").startswith("interview:"):
            return interview_call(st, hop.get("recall_caller"), None)
        if ctx.get("npc_kind") == "night":
            day = ctx.get("npc_day")
            return [rim("night", {"day": int(day) if str(day or "").isdigit() else day, "ok": False,
                                  "added": 0, "closed": 0})]
        return []
    if route == "pack_ack" and hop.get("error_code"):
        return [rim("error", {"error_code": hop.get("error_code"), "kind": "pack"})]
    # Everything else that reaches this cell is drained on purpose: a world tool's own `tool` message (its
    # call left as the intent already), sidecar sections nobody else reads, acknowledgements.
    return []


if __name__ == "__main__":
    if "STATE" not in globals():
        STATE = {}
    sys.stdout.write(json.dumps(on_message(json.load(sys.stdin), STATE)))
